update lerninhalte set daten = (daten - 'aufbau' - 'funktion' - 'physiologie' - 'klinische_relevanz' - 'wirkkette') || '{"definition": "Entzündungswerte sind Laborparameter, die anzeigen, ob und wie stark das Immunsystem auf eine Entzündung reagiert. Sie sagen nichts über den Ort der Entzündung aus und werden immer im Verlauf und zusammen mit dem klinischen Bild beurteilt.", "tabelle": {"kopf": ["Wert", "Normbereich (Erwachsene)", "Erhöht bei", "Pflegerelevanz"], "zeilen": [["CRP (C-reaktives Protein)", "< 5 mg/l", "bakterielle Infektionen, Gewebeschäden, nach OP", "steigt nach 6–12 h, Gipfel nach 24–48 h; Verlauf zeigt Therapieerfolg"], ["PCT (Procalcitonin)", "< 0,05 ng/ml", "bakterielle Infektion, Sepsis (> 0,5 ng/ml Verdacht, > 2 ng/ml hohes Sepsisrisiko)", "hilft bei der Entscheidung über Start und Ende einer Antibiose"], ["Leukozyten", "4.000–10.000/µl", "Infektion, Stress, Kortison (Leukozytose)", "Leukopenie < 4.000/µl: Infektionsgefahr, ggf. Schutzisolation"], ["BSG (Blutsenkung)", "Männer < 15 mm/h, Frauen < 20 mm/h (altersabhängig)", "chronische Entzündungen, Tumoren, Rheuma", "reagiert langsam, eher für chronische Verläufe"], ["IL-6 (Interleukin 6)", "< 7 pg/ml", "frühe Entzündungsreaktion, Sepsis", "steigt schon nach wenigen Stunden, vor CRP"]]}, "pruefungswissen": "CRP ist der wichtigste Routinewert, reagiert aber erst nach Stunden. PCT steigt vor allem bei bakteriellen Infektionen und kaum bei viralen. Ein normales CRP schließt eine sehr frühe Infektion nicht aus.", "merksatz": "IL-6 ist der Schnellste, CRP der Fleißigste, die BSG die Langsamste.", "pflegeschwerpunkt": "Vitalzeichen (Temperatur, Puls, Atemfrequenz, Blutdruck) und Bewusstsein beobachten, Laborwerte im Verlauf dokumentieren, Wunden und Zugänge auf Rötung, Schwellung, Schmerz, Überwärmung und Funktionseinschränkung kontrollieren. Bei Sepsisverdacht (z. B. qSOFA: Atemfrequenz ≥ 22/min, systolischer Blutdruck ≤ 100 mmHg, Bewusstseinsänderung) sofort den Arzt informieren."}'::jsonb, stand = current_date, geprueft_von = 'Patrick Schenkelberger, Fachpfleger Anästhesie und Intensivmedizin', geprueft_am = current_date, quelle = 'Laborreferenzwerte n. DGKL; Sepsis-3 (qSOFA)' where slug = 'entzuendungswerte';
update lerninhalte set daten = (daten - 'aufbau' - 'funktion' - 'physiologie' - 'klinische_relevanz' - 'wirkkette') || '{"definition": "Nierenwerte zeigen, wie gut die Nieren das Blut filtern. Steigen sie an, scheidet die Niere harnpflichtige Stoffe nicht mehr ausreichend aus. Kreatinin steigt allerdings erst, wenn etwa die Hälfte der Nierenfunktion verloren ist.", "tabelle": {"kopf": ["Wert", "Normbereich (Erwachsene)", "Bedeutung"], "zeilen": [["Kreatinin", "Frauen 0,5–0,9 mg/dl, Männer 0,7–1,2 mg/dl", "Abbauprodukt aus dem Muskel; hängt von Muskelmasse, Alter und Geschlecht ab"], ["eGFR (geschätzte glomeruläre Filtrationsrate)", "≥ 90 ml/min/1,73 m²", "wichtigster Wert zur Einteilung der Nierenfunktion"], ["Harnstoff", "ca. 17–43 mg/dl", "steigt auch bei Exsikkose, Blutung im Magen-Darm-Trakt und eiweißreicher Kost"], ["Kalium", "3,5–5,0 mmol/l", "bei Niereninsuffizienz Gefahr der Hyperkaliämie mit Herzrhythmusstörungen"], ["Cystatin C", "ca. 0,5–1,0 mg/l", "unabhängig von der Muskelmasse, zeigt Einschränkungen früher an"]]}, "einteilung": "Stadien der chronischen Niereninsuffizienz nach eGFR (KDIGO): G1 ≥ 90 · G2 60–89 · G3a 45–59 · G3b 30–44 · G4 15–29 · G5 < 15 ml/min/1,73 m² (Nierenversagen, Dialyse oder Transplantation).", "pruefungswissen": "Die eGFR wird aus Kreatinin, Alter und Geschlecht berechnet. Bei sehr muskelarmen, alten Menschen kann ein „normales“ Kreatinin eine eingeschränkte Nierenfunktion verdecken. Viele Medikamente (z. B. Metformin, manche Antibiotika, NSAR) müssen an die eGFR angepasst oder abgesetzt werden.", "merksatz": "Kreatinin steigt spät, Kalium gefährdet das Herz.", "pflegeschwerpunkt": "Ein- und Ausfuhr bilanzieren, Urinmenge beobachten (Oligurie unter ca. 0,5 ml/kg/h über 6 h), täglich wiegen, auf Ödeme und Atemnot achten. Kaliumreiche Lebensmittel nach ärztlicher Anordnung einschränken, Trinkmenge nach Anordnung, Medikamentenplan auf Dosisanpassung prüfen lassen. Shuntarm bei Dialysepatienten schützen: kein Blutdruck, keine Blutentnahme."}'::jsonb, stand = current_date, geprueft_von = 'Patrick Schenkelberger, Fachpfleger Anästhesie und Intensivmedizin', geprueft_am = current_date, quelle = 'KDIGO-Leitlinie CKD; Laborreferenzwerte n. DGKL' where slug = 'nierenwerte';
update lerninhalte set daten = (daten - 'aufbau' - 'funktion' - 'physiologie' - 'klinische_relevanz' - 'wirkkette') || '{"definition": "Die Spirometrie misst, wie viel Luft ein Mensch ein- und ausatmen kann und wie schnell. Sie unterscheidet eine obstruktive Störung (verengte Atemwege, z. B. Asthma, COPD) von einer restriktiven Störung (eingeschränkte Ausdehnung der Lunge, z. B. Lungenfibrose).", "tabelle": {"kopf": ["Messwert", "Bedeutung", "Typisch bei Obstruktion", "Typisch bei Restriktion"], "zeilen": [["VC / FVC (Vitalkapazität)", "maximal ein- bzw. ausatembares Volumen", "normal oder leicht vermindert", "vermindert"], ["FEV1 (Einsekundenkapazität)", "Luftmenge in der ersten Sekunde der forcierten Ausatmung", "vermindert", "vermindert, aber im Verhältnis normal"], ["FEV1/FVC (Tiffeneau-Index)", "Anteil der FEV1 an der Vitalkapazität", "< 0,7 (Obstruktion)", "normal oder erhöht"], ["PEF (Peak-Flow)", "höchster Ausatemfluss", "vermindert, schwankt bei Asthma", "meist normal"]]}, "einteilung": "Schweregrade bei COPD nach GOLD (FEV1 in % vom Sollwert, bei FEV1/FVC < 0,7): GOLD 1 ≥ 80 % · GOLD 2 50–79 % · GOLD 3 30–49 % · GOLD 4 < 30 %.", "pruefungswissen": "Der Tiffeneau-Index ist der Schlüssel zur Obstruktion. Beim Bronchospasmolysetest wird nach Gabe eines Bronchodilatators erneut gemessen: Bessert sich die FEV1 deutlich, spricht das eher für Asthma, bei COPD bleibt sie weitgehend unverändert.", "merksatz": "Obstruktion = Luft kommt schwer raus, Restriktion = Luft kommt schwer rein.", "pflegeschwerpunkt": "Ablauf vorher erklären, aufrecht sitzen lassen, Nasenklemme anlegen und zu maximaler Mitarbeit motivieren, denn das Ergebnis hängt stark von der Anstrengung ab. Bronchodilatatoren nur nach ärztlicher Anordnung vorher pausieren. Bei Asthma Peak-Flow-Tagebuch anleiten und Werte dokumentieren."}'::jsonb, stand = current_date, geprueft_von = 'Patrick Schenkelberger, Fachpfleger Anästhesie und Intensivmedizin', geprueft_am = current_date, quelle = 'GOLD-Report; Leitlinie Spirometrie (DGP); Laborreferenzwerte n. DGKL' where slug = 'lungenfunktion';
update lerninhalte set daten = (daten - 'aufbau' - 'funktion' - 'physiologie' - 'klinische_relevanz' - 'wirkkette') || '{"definition": "Der Gasaustausch findet in den Alveolen (Lungenbläschen) statt: Sauerstoff diffundiert durch die dünne alveolär-kapilläre Membran ins Blut, Kohlendioxid in die Gegenrichtung. Antrieb ist der Unterschied der Partialdrücke. Dafür müssen Belüftung (Ventilation) und Durchblutung (Perfusion) zusammenpassen.", "tabelle": {"kopf": ["Wert (arterielle BGA)", "Normbereich", "Bedeutung"], "zeilen": [["pO₂", "ca. 75–100 mmHg (sinkt mit dem Alter)", "Sauerstoffpartialdruck; erniedrigt = Hypoxämie"], ["pCO₂", "35–45 mmHg", "erhöht = Hyperkapnie (Hypoventilation), erniedrigt = Hyperventilation"], ["SaO₂ / SpO₂", "94–98 %", "Sauerstoffsättigung des Hämoglobins"], ["pH", "7,35–7,45", "unter 7,35 Azidose, über 7,45 Alkalose"], ["HCO₃⁻", "22–26 mmol/l", "Bikarbonat, metabolische Komponente"]]}, "einteilung": "Diffusionsstörung: verdickte Membran, z. B. Lungenfibrose, Lungenödem.\nVentilations-Perfusions-Missverhältnis: Belüftung oder Durchblutung fehlt, z. B. Pneumonie, Lungenembolie, COPD.\nShunt: Blut fließt an nicht belüfteten Alveolen vorbei, z. B. Atelektasen, ARDS.", "pruefungswissen": "Eine Hypoxämie ohne Hyperkapnie nennt man respiratorische Partialinsuffizienz, mit Hyperkapnie Globalinsuffizienz. Bei COPD-Patienten mit Hyperkapnie liegt die Zielsättigung meist bei 88–92 %; zu viel Sauerstoff kann die CO₂-Retention verstärken.", "merksatz": "O₂ rein, CO₂ raus, Belüftung und Durchblutung müssen zusammenpassen.", "pflegeschwerpunkt": "Atemfrequenz, Atemmuster, SpO₂, Hautfarbe und Bewusstsein beobachten. Oberkörper hochlagern, atemunterstützende Lagerung und Atemübungen (Pneumonieprophylaxe), Mobilisation fördern. Sauerstoff nur nach ärztlicher Anordnung und mit Zielbereich geben, bei Verschlechterung sofort melden."}'::jsonb, stand = current_date, geprueft_von = 'Patrick Schenkelberger, Fachpfleger Anästhesie und Intensivmedizin', geprueft_am = current_date, quelle = 'Standardlehrbücher Anatomie & Physiologie; S3-Leitlinie Sauerstoff in der Akuttherapie' where slug = 'gasaustausch';
